"""Every generated file of a task, computed from its sources.

    files(task_dir) -> {relative path: bytes}

A task's sources are `contract.yaml` and `assets/`. Everything
`files()` returns is generated: `task.toml`, `instruction.md`, `README.md`,
`MODE.md`, and the whole of `environment/` and `tests/`. `write()` makes the
directory match exactly (stale generated files are removed); `drift()` reports
every difference without writing. The evaluator modules are byte copies of
`compression_bench/harness/final_validate/`, so one source serves all tasks; the only
per-task evaluator input is `evaluator-assets/task_policy.json`.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

from instruction_render import render as render_instruction, summary

HERE = Path(__file__).resolve().parent
TASKS = HERE.parent
REPO = TASKS.parent
TEMPLATE = TASKS / "_template"
FINAL_VALIDATE = REPO / "compression_bench" / "harness" / "final_validate"
ENVIRONMENTS = REPO / "compression_bench" / "environments"

GENERATED_TOP = ("task.toml", "instruction.md", "README.md", "MODE.md")
GENERATED_DIRS = ("environment", "tests")

# The evaluator modules every copy carries, and the extra public-Checker ones.
VERIFIER_MODULES = ("evaluate.py", "inference_runtime.py", "decode_benchmark.py", "ppl_benchmark.py",
                    "model_memory.py", "tokenizer_assets.py", "task_policy.py",
                    "accuracy_benchmark.py", "fidelity.py", "own_compression.py")
CHECKER_MODULES = VERIFIER_MODULES + ("evaluate_public.py", "server.py")
EVALUATOR_DATA = ("ppl_config.json", "ppl_inputs.json", "decode_config.json", "decode_inputs.json")
# The hidden correctness gate's inputs: the Verifier's copy only.
ACCURACY_DATA = ("accuracy_config.json", "accuracy_inputs.json")
AGENT_TOOLS = ("check_submission.py", "model_inventory.py", "submission_guard.py")

PLATFORM_PATCHES = {
    # name: (source file under platform-gguf/patches, Dockerfile lines)
    "text-architecture": ("patch_gguf_text_architecture.py", [
        "COPY platform/patch_gguf_text_architecture.py /opt/compression-bench-platform/patch_gguf_text_architecture.py",
        # Applied, then removed: a build-time repair, nothing the agent needs to read.
        "RUN python3 /opt/compression-bench-platform/patch_gguf_text_architecture.py && rm /opt/compression-bench-platform/patch_gguf_text_architecture.py"]),
    "q8-tail": ("patch_gguf_q8_tail.py", [
        "COPY platform/patch_gguf_q8_tail.py /opt/compression-bench-platform/patch_gguf_q8_tail.py",
        # Applied, then removed: a build-time repair, nothing the agent needs to read.
        "RUN python3 /opt/compression-bench-platform/patch_gguf_q8_tail.py && rm /opt/compression-bench-platform/patch_gguf_q8_tail.py"]),
    "operator-ops": ("vllm_gguf_plugin_ops.py", [
        "# Platform repair of the GGUF plugin's ops; scoring and evaluation assets unchanged.",
        "COPY platform/vllm_gguf_plugin_ops.py /usr/local/lib/python3.12/dist-packages/vllm_gguf_plugin/ops.py",
        'RUN echo "{sha256}  /usr/local/lib/python3.12/dist-packages/vllm_gguf_plugin/ops.py" | sha256sum -c -']),
}
#: The runtime the Checker and Verifier inherit from the agent image is checked,
#: not reinstalled: vLLM and the humming-kernels it pins.
VLLM_VERSION = "0.32.0"
HUMMING_VERSION = "0.1.17"
RUNTIME_CHECK = [
    "RUN python3 -c \"from importlib.metadata import version; "
    f"assert version('vllm') == '{VLLM_VERSION}'; assert version('humming-kernels') == '{HUMMING_VERSION}'\"",
]
HEADER = "# GENERATED by compression_tasks/_manage/taskctl.py render from contract.yaml; do not edit."


def load_contract(task_dir: Path) -> dict:
    import yaml
    return yaml.safe_load((Path(task_dir) / "contract.yaml").read_text())


def images() -> dict:
    return json.loads((ENVIRONMENTS / "images.json").read_text())


def agent_image(contract: dict) -> str:
    """The agent's image: `platform-gguf` (agent-base plus the pinned GGUF plugin),
    the one platform every task runs on (`platform.image: gguf`)."""
    return images()["platform-gguf"]["tag"]


def runtime_image(contract: dict) -> str:
    """The Checker and Verifier image: the agent's own runtime, so the three containers
    carry one vLLM, one Humming and one compatibility patch."""
    return agent_image(contract)


def task_policy(contract: dict) -> dict:
    evaluation = contract["evaluation"]
    return {
        "schema": "compression-bench-task-policy-v1",
        "task_id": contract["task_id"],
        "size_limit_gib": contract["capacity_gib"],
        "payload_rule": evaluation["payload_rule"],
        "link_rule": evaluation["link_rule"],
        "official_tokenizer_files": list(evaluation["official_tokenizer_files"]),
        "ppl_protocol": evaluation["ppl_protocol"],
        "scoring_protocol": evaluation["scoring_protocol"],
        "quality_rule": evaluation["quality_rule"],
        "quality": dict(evaluation["quality"]),
        "smoke_prompt": evaluation["smoke_prompt"],
        "hidden_reference_fields": evaluation["hidden_reference_fields"],
    }


def model_memory_policy(contract: dict) -> dict:
    return {"protocol": "resident-model-storage-v1", "limit_gib": contract["capacity_gib"],
            "scope": "resident model storages, not total GPU memory",
            "adapter": "vllm-torch-storage-audited-v1", "review_required": True}


def evaluation_profiles(contract: dict) -> dict:
    profiles = {"formal": {"tokenizer": "tokenizer", "size_limit_gib": contract["capacity_gib"],
                           "score": True, "decode_assets": ".", "ppl_assets": ".", "ppl_split": "public"}}
    if contract.get("debug_model"):
        profiles["debug-9b"] = {"tokenizer": "/input/debug-model", "size_limit_gib": 32, "score": False,
                                "decode_assets": "debug-9b", "ppl_assets": "debug-9b",
                                "ppl_split": "debug-9b"}
    return profiles


def _json(value) -> bytes:
    return (json.dumps(value, indent=2) + "\n").encode()


def _toml_value(value) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return repr(value)
    if isinstance(value, str):
        return json.dumps(value)
    if isinstance(value, list):
        return "[" + ", ".join(_toml_value(v) for v in value) + "]"
    raise TypeError(f"no TOML form for {value!r}")


def task_toml(contract: dict) -> bytes:
    budget = contract["budget"]
    metadata = {
        "task_id": contract["task_id"],
        "task_hash": contract["task_hash"],
        "model": contract["model"]["id"],
        "model_revision": contract["model"]["revision"],
        "size_limit_gib": contract["capacity_gib"],
        "scoring_protocol": contract["evaluation"]["scoring_protocol"],
        "ppl_protocol": contract["evaluation"]["ppl_protocol"],
        "quality_rule": contract["evaluation"]["quality_rule"],
        "platform": contract["platform"]["image"],
        **(contract.get("metadata") or {}),
    }
    if contract["reference"].get("model"):
        metadata.setdefault("reference_model", contract["reference"]["model"])
        metadata.setdefault("reference_revision", contract["reference"]["revision"])
    lines = [
        'schema_version = "1.4"',
        HEADER,
        "# Submission is a persistent host bind mount, not a Harbor download/upload.",
        "artifacts = []",
        "",
        "[task]",
        f'name = "compression-bench/{contract["task_id"]}"',
        f"version = {_toml_value(str(contract['version']))}",
        f"description = {_toml_value(contract['description'])}",
        f"keywords = {_toml_value(list(contract['keywords']))}",
        "",
        "[metadata]",
        *(f"{key} = {_toml_value(value)}" for key, value in metadata.items()),
        "",
        "[verifier]",
        f"timeout_sec = {float(budget['verifier_timeout_s'])!r}",
        "",
        "# The Verifier gets its own no-network container; the lifecycle runs it host-side",
        "# after the deadline (compression_bench/harness/final_validate/tools/validate_evolve.py).",
        "[verifier.environment]",
        'network_mode = "no-network"',
        f"build_timeout_sec = {float(budget['build_timeout_s'])!r}",
        "",
        "[agent]",
        f"timeout_sec = {float(budget['agent_hours'] * 3600)!r}",
        'network_mode = "allowlist"',
        "allowed_hosts = []",
        "",
        "[environment]",
        'network_mode = "public"',
        f"build_timeout_sec = {float(budget['build_timeout_s'])!r}",
        "",
    ]
    return "\n".join(lines).encode()


def _patch_lines(contract: dict) -> list[str]:
    lines: list[str] = []
    for name in contract["platform"]["patches"]:
        source, block = PLATFORM_PATCHES[name]
        digest = hashlib.sha256((ENVIRONMENTS / "platform-gguf" / "patches" / source).read_bytes()).hexdigest()
        lines += ["", *(line.format(sha256=digest) for line in block)]
    return lines


def _patch_files(contract: dict, prefix: str) -> dict[str, bytes]:
    out = {}
    for name in contract["platform"]["patches"]:
        source = PLATFORM_PATCHES[name][0]
        out[f"{prefix}/platform/{source}"] = (ENVIRONMENTS / "platform-gguf" / "patches" / source).read_bytes()
    return out


def environment_dockerfile(contract: dict) -> bytes:
    lines = [
        HEADER,
        f"FROM {agent_image(contract)}",
        "",
        "RUN mkdir -p /app/work /app/submission",
        "COPY check_submission.py model_inventory.py /app/",
        "COPY inference.py submission_guard.py /app/",
        "RUN chmod 0555 /app/check_submission.py /app/model_inventory.py \\",
        "    && python3 /app/model_inventory.py --help >/dev/null",
        "WORKDIR /app",
        *_patch_lines(contract),
        "",
    ]
    return "\n".join(lines).encode()


def checker_dockerfile(contract: dict) -> bytes:
    lines = [
        HEADER,
        f"FROM {runtime_image(contract)}",
        "",
        *RUNTIME_CHECK,
        "",
        *copy_lines(("server.py", "evaluate_public.py", *VERIFIER_MODULES), "/checker/"),
        "COPY evaluator-assets/ /checker/evaluator-assets/",
        "# The evaluator and its public inputs are read-only in the running Checker.",
        "RUN chmod -R a-w /checker && chmod 0555 /checker/server.py /checker/evaluate_public.py",
        *_patch_lines(contract),
        "",
        'ENTRYPOINT ["python3", "/checker/server.py"]',
        "",
    ]
    return "\n".join(lines).encode()


def copy_lines(names: tuple[str, ...], target: str, per_line: int = 5) -> list[str]:
    """COPY every evaluator module into its image, from the one module list, so no
    module an image imports can be left out."""
    return [f"COPY {' '.join(names[i:i + per_line])} {target}" for i in range(0, len(names), per_line)]


def verifier_dockerfile(contract: dict) -> bytes:
    lines = [
        HEADER,
        f"FROM {runtime_image(contract)}",
        "",
        *RUNTIME_CHECK,
        "",
        "ENTRYPOINT []",
        *copy_lines(("test.sh", *VERIFIER_MODULES), "/tests/"),
        "COPY evaluator-assets /tests/evaluator-assets",
        "# The evaluator and its hidden inputs are read-only in the running Verifier.",
        "RUN chmod -R a-w /tests && chmod 0555 /tests/test.sh /tests/evaluate.py",
        "WORKDIR /tests",
        *_patch_lines(contract),
        "",
    ]
    return "\n".join(lines).encode()


def _tree(source: Path, prefix: str) -> dict[str, bytes]:
    return {f"{prefix}/{p.relative_to(source).as_posix()}": p.read_bytes()
            for p in sorted(source.rglob("*")) if p.is_file()}


def _assets_readme(public: bool) -> bytes:
    text = (TEMPLATE / "docker" / ("assets-public.md" if public else "assets-hidden.md")).read_text()
    return text.encode()


def files(task_dir: Path) -> dict[str, bytes]:
    task_dir = Path(task_dir)
    contract = load_contract(task_dir)
    assets = task_dir / "assets"
    docker = TEMPLATE / "docker"
    out: dict[str, bytes] = {}

    out["task.toml"] = task_toml(contract)
    out["instruction.md"] = render_instruction(task_dir, contract).encode()
    out["README.md"] = summary(task_dir, contract).encode()
    out["MODE.md"] = (docker / "MODE.md").read_text().replace(
        "{{AGENT_IMAGE}}", agent_image(contract)).replace(
        "{{RUNTIME_IMAGE}}", runtime_image(contract)).encode()

    # environment/: the agent's container and the public Checker sidecar.
    out["environment/Dockerfile"] = environment_dockerfile(contract)
    out["environment/docker-compose.yaml"] = (docker / "environment" / "docker-compose.yaml.in").read_text().replace(
        "{{PUBLIC_CHECK_TIMEOUT_S}}", str(contract["budget"]["public_check_timeout_s"])).encode()
    for name in AGENT_TOOLS:
        out[f"environment/{name}"] = (docker / "environment" / name).read_bytes()
    out["environment/inference.py"] = (TEMPLATE / "starters" / f"inference.{contract['starter']}.py").read_bytes()
    out.update(_patch_files(contract, "environment"))

    checker = "environment/public-checker"
    out[f"{checker}/Dockerfile"] = checker_dockerfile(contract)
    for name in CHECKER_MODULES:
        out[f"{checker}/{name}"] = (FINAL_VALIDATE / name).read_bytes()
    out.update(_patch_files(contract, checker))
    ea = f"{checker}/evaluator-assets"
    out[f"{ea}/task_policy.json"] = _json(task_policy(contract))
    out[f"{ea}/model_memory_policy.json"] = _json(model_memory_policy(contract))
    out[f"{ea}/evaluation_profiles.json"] = _json(evaluation_profiles(contract))
    out[f"{ea}/README.md"] = _assets_readme(public=True)
    out.update(_tree(assets / "tokenizer", f"{ea}/tokenizer"))
    for name in EVALUATOR_DATA:
        out[f"{ea}/{name}"] = (assets / "public" / name).read_bytes()
    if contract.get("debug_model"):
        for name in EVALUATOR_DATA:
            out[f"{ea}/debug-9b/{name}"] = (assets / "debug-9b" / name).read_bytes()

    # tests/: the hidden Verifier. Hidden inputs exist only here.
    out["tests/Dockerfile"] = verifier_dockerfile(contract)
    out["tests/docker-compose.yaml"] = (docker / "tests" / "docker-compose.yaml").read_bytes()
    out["tests/test.sh"] = (docker / "tests" / "test.sh").read_bytes()
    for name in VERIFIER_MODULES:
        out[f"tests/{name}"] = (FINAL_VALIDATE / name).read_bytes()
    out.update(_patch_files(contract, "tests"))
    out["tests/evaluator-assets/task_policy.json"] = _json(task_policy(contract))
    out["tests/evaluator-assets/model_memory_policy.json"] = _json(model_memory_policy(contract))
    out["tests/evaluator-assets/README.md"] = _assets_readme(public=False)
    out.update(_tree(assets / "tokenizer", "tests/evaluator-assets/tokenizer"))
    for name in EVALUATOR_DATA + ACCURACY_DATA:
        out[f"tests/evaluator-assets/{name}"] = (assets / "hidden" / name).read_bytes()
    return out


EXECUTABLE = ("tests/test.sh",)


def _on_disk(task_dir: Path) -> dict[str, Path]:
    found = {name: task_dir / name for name in GENERATED_TOP if (task_dir / name).exists()}
    for directory in GENERATED_DIRS:
        root = task_dir / directory
        if root.is_dir():
            for path in root.rglob("*"):
                if path.is_file() or path.is_symlink():
                    found[path.relative_to(task_dir).as_posix()] = path
    return found


def drift(task_dir: Path) -> list[str]:
    """Every generated file that is missing, stale or extra; empty when in step."""
    task_dir = Path(task_dir)
    want = files(task_dir)
    have = _on_disk(task_dir)
    problems = []
    for name, data in sorted(want.items()):
        if name not in have:
            problems.append(f"missing generated file {name}")
        elif have[name].is_symlink() or have[name].read_bytes() != data:
            problems.append(f"stale generated file {name} (run taskctl render)")
    for name in sorted(set(have) - set(want)):
        problems.append(f"extra file in a generated directory: {name}")
    for name in EXECUTABLE:
        path = task_dir / name
        if path.exists() and not path.stat().st_mode & 0o111:
            problems.append(f"{name} is not executable")
    return problems


def write(task_dir: Path) -> list[str]:
    """Make the task's generated files match its sources; returns what changed."""
    task_dir = Path(task_dir)
    want = files(task_dir)
    have = _on_disk(task_dir)
    changed = []
    for name in sorted(set(have) - set(want)):
        have[name].unlink()
        changed.append(f"removed {name}")
    for name, data in sorted(want.items()):
        path = task_dir / name
        if not path.is_file() or path.read_bytes() != data:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(data)
            changed.append(f"wrote {name}")
        if name in EXECUTABLE:
            path.chmod(0o755)
    for directory in GENERATED_DIRS:
        root = task_dir / directory
        for sub in sorted((p for p in root.rglob("*") if p.is_dir()), key=lambda p: -len(p.parts)):
            if not any(sub.iterdir()):
                sub.rmdir()
    return changed


__all__ = ["files", "drift", "write", "load_contract", "task_policy"]
